"""The arm table: one row per payload, with the manifest's hash beside it.

Generated so that adding a payload to `shapes.json` adds a row here and nothing is
registered by hand. The oracle is `ffi/schema/generated/manifest.json`, which the rust
slice validated against prost 0.14.4 and a second independent encoder; a slice that
disagrees with a hash has a defect in itself (design/SHAPES.md).
"""
import json
import os

from cppnames import snake

HEAD = ("// @generated by ffi/poc/cpp/gen/generate.py from ffi/schema/shapes.json"
        " and manifest.json. Do not edit.\n")

NS = "armonik::ffi::shapes::v1"


def emit(ir):
    here = os.path.dirname(os.path.abspath(__file__))
    mpath = os.path.abspath(os.path.join(here, "..", "..", "..", "schema", "generated",
                                         "manifest.json"))
    man = json.load(open(mpath))["payloads"]
    o = [HEAD, "#ifndef AK_CASES_H", "#define AK_CASES_H", "",
         "// X(id, Root, snake_root, payload_suffix, sha256, bytes)",
         "#define AK_CASES(X) \\"]
    rows = []
    for pid, spec in ir.schema["payloads"].items():
        root = spec["root"]
        if root not in ir.messages or spec.get("interleaved"):
            continue
        m = man[pid]
        rows.append('  X("%s", %s, %s, %s, "%s", %d)'
                    % (pid, root, snake(root), pid.replace(".", "_").lower(),
                       m["sha256"], m["bytes"]))
    o.append(" \\\n".join(rows))
    o.append("")
    o.append("// X(Root, snake_root): every message this slice can ROOT a decode at, which")
    o.append("// is what decides which rows of ffi/corpus are in scope for it. Generated")
    o.append("// from the same ROOTS list the codec is generated from, so the corpus")
    o.append("// consumer cannot claim a scope the codec does not have.")
    o.append("#define AK_ROOTS(X) \\")
    o.append(" \\\n".join("  X(%s, %s)" % (r, snake(r)) for r in ir.roots))
    o.append("")
    o.append("// P7.1 is DECODE ONLY: no canonical writer can produce interleaved repeated")
    o.append("// fields, so it is validated by decoding the committed vector and re-encoding")
    o.append("// contiguously to a permutation of the same (tag, wire type, body) triples.")
    o.append('#define AK_P71_VECTOR "P7_1.bin"')
    o.append('#define AK_P71_SHA "%s"' % man["P7.1"]["sha256"])
    o.append("")
    o.append("#endif")
    o.append("")
    return "\n".join(o)
